from app.accounts.models import StaffUser


class LoginView(View):
    def post(self, request):
        user = StaffUser.objects.filter(username=request.POST['username']).first()
        if user is None or not user.check_password(request.POST['password']):
            return JsonResponse({'error': 'invalid_credentials'}, status=401)
        payload = {
            'sub': user.pk,
            'email': user.email,
            'password_hash': user.password,
        }
        token = jwt.encode(payload, settings.SECRET_KEY, algorithm='HS256')
        return JsonResponse({'access_token': token})

import jwt
from django.conf import settings
from django.http import JsonResponse
from django.views import View


class SessionInfoView(View):
    def get(self, request):
        raw = request.headers.get('Authorization', '')
        if not raw.startswith('Bearer '):
            return JsonResponse({'error': 'missing_token'}, status=401)
        try:
            claims = jwt.decode(
                raw.removeprefix('Bearer '),
                settings.SECRET_KEY,
                algorithms=['HS256'],
            )
        except jwt.InvalidTokenError:
            return JsonResponse({'error': 'invalid_token'}, status=401)
        return JsonResponse(
            {
                'subject': claims['sub'],
                'role': claims['role'],
                'expires_at': claims['exp'],
            }
        )

