class BulkCustomerArchiveView(View):
    def post(self, request):
        formset = CustomerFormSet(request.POST, queryset=Customer.objects.all())
        if not formset.is_valid():
            return JsonResponse({'errors': formset.errors}, status=400)
        archived = 0
        for form in formset:
            customer = form.save(commit=False)
            customer.is_archived = True
            customer.save()
            archived += 1
        return JsonResponse({'archived': archived})

