from app.billing.models import Invoice


@strawberry.type
class InvoiceExport:
    count: int
    checksum: str


@strawberry.type
class Mutation:
    @strawberry.mutation
    def archive_invoices(self, year: int) -> InvoiceExport:
        rows = Invoice.objects.filter(issued_at__year=year)
        payload = ','.join(str(row.number) for row in rows).encode()
        checksum = hashlib.sha256(payload).hexdigest()
        return InvoiceExport(count=rows.count(), checksum=checksum)


