@strawberry.type
class ResetRequestResult:
    requested: bool


def build_reset_token(user):
    payload = {'sub': user.pk, 'scope': 'password_reset'}
    return jwt.encode(payload, settings.RESET_SECRET, algorithm='HS256')


@strawberry.type
class Mutation:
    @strawberry.mutation
    def request_password_reset(self, email: str) -> ResetRequestResult:
        user = User.objects.filter(email=email).first()
        if user is not None:
            token = build_reset_token(user)
            send_mail(
                'Reset your password',
                'https://app.example.com/reset?token=' + token,
                'no-reply@example.com',
                [user.email],
            )
        return ResetRequestResult(requested=True)

