router = APIRouter()


class BaseResetHandler:
    def issue_token(self):
        return secrets.token_urlsafe(32)


class SmsResetHandler(BaseResetHandler):
    def deliver(self, user, token):
        send_sms(user.phone, 'reset code: ' + token)


async def reset_session(session: AsyncSession = Depends(get_session)):
    yield session


@router.post('/auth/password-reset')
async def request_password_reset(
    email: str,
    session: AsyncSession = Depends(reset_session),
):
    repo = UserRepository(session)
    user = await repo.find_by_email(email)
    if user is not None:
        handler = SmsResetHandler()
        handler.deliver(user, handler.issue_token())
    return {'detail': 'if the account exists, a code was sent'}

